presets.bg_css:
.background {
  background:
    radial-gradient(circle at 20% 18%, rgba(255, 245, 210, 0.32) 0 2px, transparent 2.5px),
    radial-gradient(circle at 78% 24%, rgba(255, 230, 245, 0.28) 0 2px, transparent 2.5px),
    radial-gradient(circle at 30% 72%, rgba(255, 245, 210, 0.22) 0 1.5px, transparent 2px),
    radial-gradient(circle at 82% 78%, rgba(255, 230, 245, 0.24) 0 1.5px, transparent 2px),
    linear-gradient(180deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02)),
    linear-gradient(145deg, #f7d9e8 0%, #e6c8ea 42%, #cdb8e8 72%, #b39fd8 100%);

  background-repeat: repeat, repeat, repeat, repeat, no-repeat, no-repeat;
  background-size: 140px 140px, 180px 180px, 120px 120px, 160px 160px, 100% 100%, 100% 100%;
  background-position: 0 0, 20px 30px, 10px 15px, 40px 50px, center, center;
}

presets.fg_css:
.foreground {
  pointer-events: none;
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  overflow: hidden;
  border-radius: 10px;

  background: transparent;

  border: 3px solid #f3d48e;

  box-shadow:
    inset 0 0 0 3px #fffaf0,
    inset 0 0 0 6px #e6a9bf,
    inset 0 0 0 8px #ffe7a8,
    inset 0 0 0 12px rgba(255, 250, 245, 0.9),
    inset 0 0 0 13px rgba(213, 157, 185, 0.95);
}

.foreground::before {
  content: "✦  ✿  ♡  ✿  ✦";
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;

  font-size: 22px;
  letter-spacing: 8px;
  color: #f3d48e;
}

.foreground::after {
  content: "✦  ♡  ✦";
  position: absolute;
  bottom: 14px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;

  font-size: 22px;
  letter-spacing: 10px;
  color: #f3d48e;
}
